<template><div class="page">
 <div class="page-header"><div><div class="page-title">基础字典管理</div><div class="text-muted subtitle">统一维护铺位使用的楼层、业态和工程参数</div></div><el-button type="primary" @click="openCreate">新增{{typeLabel}}</el-button></div>
