  <el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注" min-width="180"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="已被铺位使用的规格不能删除，可改为停用。确定删除？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column>
 </el-table></div>
 <div v-else-if="type==='AIR_CONDITIONER_SPEC'" class="table-card"><el-table :data="airConditionerRows" v-loading="loading" border><el-table-column prop="specCode" label="规格编码" min-width="120"/><el-table-column prop="model" label="空调型号" min-width="180"/><el-table-column label="空调类型" min-width="120"><template #default="{row}">{{airConditionerTypeLabel(row.equipmentType)}}</template></el-table-column><el-table-column prop="ratedPowerKw" label="功率（kW）" min-width="110"/><el-table-column prop="airflowCmh" label="额定出风量（m³/h）" min-width="155"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="remark" label="备注" min-width="160"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="已被铺位使用的型号不能删除，可改为停用。确定删除？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div>
 <div v-else class="table-card"><el-table :data="switchRows" v-loading="loading" border><el-table-column prop="specCode" label="规格编码" min-width="120"/><el-table-column prop="brand" label="品牌" min-width="100"/><el-table-column prop="switchModel" label="开关型号" min-width="150"/><el-table-column prop="switchType" label="类型" min-width="110"/><el-table-column prop="poleCount" label="极数" width="80"/><el-table-column prop="ratedCurrentA" label="额定电流(A)" min-width="115"/><el-table-column prop="breakingCapacityKa" label="分断能力(kA)" min-width="120"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status===1?'success':'info'">{{row.status===1?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openEdit(row)">编辑</el-button><el-popconfirm title="已被铺位使用的开关不能删除，可改为停用。确定删除？" @confirm="remove(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div>
 <el-dialog v-model="visible" :title="form.id?'编辑字典项':`新增${typeLabel}`" width="560px"><el-form ref="formRef" :model="form" :rules="type==='CABLE'?cableRules:type==='SWITCH'?switchRules:type==='AIR_CONDITIONER_SPEC'?airConditionerRules:rules" label-width="130px">
  <template v-if="type==='CABLE'"><el-form-item label="规格编码" prop="specCode"><el-input v-model="form.specCode" placeholder="例如：YJV-4X35-1X16"/></el-form-item><el-form-item label="电缆型号" prop="cableModel"><el-input v-model="form.cableModel" placeholder="例如：YJV"/></el-form-item><el-form-item label="规格" prop="specification"><el-input v-model="form.specification" placeholder="例如：4×35+1×16 mm²"/></el-form-item><el-form-item label="单根额定电流" prop="ratedCurrentA"><el-input-number v-model="form.ratedCurrentA" :min="0.01" :precision="2"/><span class="unit">A</span></el-form-item><el-form-item label="单根承载功率" prop="ratedPowerKw"><el-input-number v-model="form.ratedPowerKw" :min="0.01" :precision="2"/><span class="unit">kW</span></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></template>
  <template v-else-if="type==='SWITCH'"><el-form-item label="规格编码" prop="specCode"><el-input v-model="form.specCode" placeholder="例如：DZ47-3P-63A"/></el-form-item><el-form-item label="品牌"><el-input v-model="form.brand"/></el-form-item><el-form-item label="开关型号" prop="switchModel"><el-input v-model="form.switchModel" placeholder="例如：DZ47-63 C63"/></el-form-item><el-form-item label="开关类型"><el-select v-model="form.switchType" clearable><el-option label="微型断路器" value="MCB"/><el-option label="塑壳断路器" value="MCCB"/><el-option label="漏电断路器" value="RCBO"/><el-option label="隔离开关" value="ISOLATOR"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="极数" prop="poleCount"><el-select v-model="form.poleCount"><el-option v-for="p in ['1P','2P','3P','4P']" :key="p" :label="p" :value="p"/></el-select></el-form-item><el-form-item label="额定电流" prop="ratedCurrentA"><el-input-number v-model="form.ratedCurrentA" :min="0.01" :precision="2"/><span class="unit">A</span></el-form-item><el-form-item label="分断能力"><el-input-number v-model="form.breakingCapacityKa" :min="0.01" :precision="2"/><span class="unit">kA</span></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></template>
  <template v-else-if="type==='AIR_CONDITIONER_SPEC'"><el-form-item label="规格编码" prop="specCode"><el-input v-model="form.specCode" placeholder="例如：FP-68"/></el-form-item><el-form-item label="空调型号" prop="model"><el-input v-model="form.model" placeholder="请输入设备铭牌型号"/></el-form-item><el-form-item label="空调类型" prop="equipmentType"><el-select v-model="form.equipmentType"><el-option label="风机盘管" value="FAN_COIL"/><el-option label="吊柜式空调" value="HANGING_CABINET"/><el-option label="其他" value="OTHER"/></el-select></el-form-item><el-form-item label="额定功率" prop="ratedPowerKw"><el-input-number v-model="form.ratedPowerKw" :min="0.01" :precision="2"/><span class="unit">kW</span></el-form-item><el-form-item label="额定出风量" prop="airflowCmh"><el-input-number v-model="form.airflowCmh" :min="1" :precision="0"/><span class="unit">m³/h</span></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></template>
  <template v-else>
  <el-form-item label="分类"><el-input :model-value="typeLabel" disabled/></el-form-item><el-form-item label="取值编码" prop="itemValue"><el-input v-model="form.itemValue" placeholder="例如：F1"/></el-form-item><el-form-item label="显示名称" prop="itemLabel"><el-input v-model="form.itemLabel" placeholder="例如：一层"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-switch v-model="form.status" :active-value="1" :inactive-value="0"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item>
  </template>
 </el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
</div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,type FormInstance}from'element-plus';import{dictionaryApi,cableSpecificationApi,powerSwitchSpecificationApi,airConditionerSpecificationApi,type CableSpecification,type PowerSwitchSpecification,type AirConditionerSpecification,type DictionaryItem,type DictionaryType}from'@/api/system'
type PageType=DictionaryType|'CABLE'|'SWITCH';const types=[{value:'FLOOR',label:'楼层'},{value:'BUSINESS_TYPE',label:'业态'},{value:'METER_LOCATION',label:'电表位置'},{value:'WATER_METER_CALIBER',label:'水表口径'},{value:'DRAINAGE_PIPE_CALIBER',label:'排水管口径'},{value:'EXHAUST_FAN',label:'排油烟风机'},{value:'FRESH_AIR_UNIT',label:'补风机'},{value:'AIR_CONDITIONER_SPEC',label:'空调设备规格'},{value:'NATURAL_GAS_CALIBER',label:'天然气管径'},{value:'POWER_NODE_TYPE',label:'配电节点类型'},{value:'WATER_SUPPLY_NODE_TYPE',label:'供水节点类型'},{value:'WATER_SUPPLY_PIPE_SPEC',label:'供水管道规格'},{value:'DRAINAGE_NODE_TYPE',label:'排水节点类型'},{value:'DRAINAGE_MEDIUM',label:'排水性质'},{value:'OIL_EXHAUST_NODE_TYPE',label:'排油烟节点类型'},{value:'FRESH_AIR_NODE_TYPE',label:'补风节点类型'},{value:'AIR_DUCT_SPEC',label:'排烟/补风管规格'},{value:'CABLE',label:'电缆规格'},{value:'SWITCH',label:'供电开关规格'}] as {value:PageType,label:string}[]
const type=ref<PageType>('FLOOR'),rows=ref<DictionaryItem[]>([]),cableRows=ref<CableSpecification[]>([]),switchRows=ref<PowerSwitchSpecification[]>([]),airConditionerRows=ref<AirConditionerSpecification[]>([]),loading=ref(false),saving=ref(false),visible=ref(false),formRef=ref<FormInstance>();const form=reactive<any>({});const typeLabel=computed(()=>types.find(t=>t.value===type.value)?.label||'')
const rules={itemValue:[{required:true,message:'请输入取值编码'}],itemLabel:[{required:true,message:'请输入显示名称'}]}
const cableRules={specCode:[{required:true,message:'请输入规格编码'}],cableModel:[{required:true,message:'请输入电缆型号'}],specification:[{required:true,message:'请输入电缆规格'}],ratedCurrentA:[{required:true,message:'请输入额定电流'}],ratedPowerKw:[{required:true,message:'请输入承载功率'}]}
const switchRules={specCode:[{required:true,message:'请输入规格编码'}],switchModel:[{required:true,message:'请输入开关型号'}],poleCount:[{required:true,message:'请选择极数'}],ratedCurrentA:[{required:true,message:'请输入额定电流'}]}
const airConditionerRules={specCode:[{required:true,message:'请输入规格编码'}],model:[{required:true,message:'请输入空调型号'}],equipmentType:[{required:true,message:'请选择空调类型'}],ratedPowerKw:[{required:true,message:'请输入额定功率'}],airflowCmh:[{required:true,message:'请输入额定出风量'}]}
function airConditionerTypeLabel(v:string){return v==='FAN_COIL'?'风机盘管':v==='HANGING_CABINET'?'吊柜式空调':'其他'}
async function load(){loading.value=true;try{if(type.value==='CABLE')cableRows.value=await cableSpecificationApi.list(false) as any;else if(type.value==='SWITCH')switchRows.value=await powerSwitchSpecificationApi.list(false) as any;else if(type.value==='AIR_CONDITIONER_SPEC')airConditionerRows.value=await airConditionerSpecificationApi.list(false) as any;else rows.value=await dictionaryApi.list(type.value,false) as any}finally{loading.value=false}}
function openCreate(){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,type.value==='CABLE'?{id:0,specCode:'',cableModel:'',specification:'',ratedCurrentA:null,ratedPowerKw:null,sortOrder:0,status:1,remark:''}:type.value==='SWITCH'?{id:0,specCode:'',brand:'',switchModel:'',switchType:'MCB',poleCount:'3P',ratedCurrentA:null,breakingCapacityKa:null,sortOrder:0,status:1,remark:''}:type.value==='AIR_CONDITIONER_SPEC'?{id:0,specCode:'',model:'',equipmentType:'FAN_COIL',ratedPowerKw:null,airflowCmh:null,sortOrder:0,status:1,remark:''}:{id:0,itemValue:'',itemLabel:'',sortOrder:0,status:1,remark:''});visible.value=true}function openEdit(row:any){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row);visible.value=true}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{if(type.value==='CABLE'){const data={specCode:form.specCode,cableModel:form.cableModel,specification:form.specification,ratedCurrentA:form.ratedCurrentA,ratedPowerKw:form.ratedPowerKw,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await cableSpecificationApi.update(form.id,data);else await cableSpecificationApi.create(data)}else if(type.value==='SWITCH'){const data={specCode:form.specCode,brand:form.brand,switchModel:form.switchModel,switchType:form.switchType,poleCount:form.poleCount,ratedCurrentA:form.ratedCurrentA,breakingCapacityKa:form.breakingCapacityKa,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await powerSwitchSpecificationApi.update(form.id,data);else await powerSwitchSpecificationApi.create(data)}else if(type.value==='AIR_CONDITIONER_SPEC'){const data={specCode:form.specCode,model:form.model,equipmentType:form.equipmentType,ratedPowerKw:form.ratedPowerKw,airflowCmh:form.airflowCmh,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await airConditionerSpecificationApi.update(form.id,data);else await airConditionerSpecificationApi.create(data)}else{const data={dictType:type.value,itemValue:form.itemValue,itemLabel:form.itemLabel,sortOrder:form.sortOrder,status:form.status,remark:form.remark};if(form.id)await dictionaryApi.update(form.id,data);else await dictionaryApi.create(data)}ElMessage.success('保存成功');visible.value=false;await load()}finally{saving.value=false}}
async function remove(row:any){if(type.value==='CABLE')await cableSpecificationApi.remove(row.id);else if(type.value==='SWITCH')await powerSwitchSpecificationApi.remove(row.id);else if(type.value==='AIR_CONDITIONER_SPEC')await airConditionerSpecificationApi.remove(row.id);else await dictionaryApi.remove(row.id);ElMessage.success('删除成功');await load()}onMounted(load)
</script><style scoped>.subtitle{font-size:13px;margin-top:4px}.unit{margin-left:8px;color:#606266}</style>
